def contains(big, small):
    v=variants(small)
    bh,bw=big.shape; sh,sw=small.shape
    for i in range(bh-sh+1):
        for j in range(bw-sw+1):
            if norm(big[i:i+sh,j:j+sw]) in v: return True
    return False
