def props(a, val=1):
    p={}
    p['cells']=int((a==val).sum())
    p['area']=a.size
    filled=ndimage.binary_fill_holes(a==val)
    p['holes']=int((filled & ~(a==val)).sum())
    sym=[]
    t=(a==val)
    for name,x in [('id',t),('rot90',np.rot90(t)),('rot180',np.rot90(t,2)),('rot270',np.rot90(t,3)),
                   ('flip',np.fliplr(t)),('flipud',np.flipud(t)),('d1',t.T),('d2',np.fliplr(np.rot90(t)))]:
        if name=='id' or x.shape==t.shape:
            sym.append(name if np.array_equal(x,t) else None)
    p['sym']=[s for s in sym if s]
    p['even']=p['cells']%2==0
    return p

def clusters(G, val=1):
    lab_,n_=ndimage.label(G==val, structure=np.ones((3,3)))
    out=[]
    for i in range(1,n_+1):
        ys,xs=np.where(lab_==i)
        out.append(G[ys.min():ys.max()+1, xs.min():xs.max()+1].copy())
    return out

